/*
GPT-2 Transformer Neural Net trained in raw CUDA
Non-trivial notes to be aware of:

We are being clever in the backward pass to conserve memory.
In particular, all parameters use a += in the backward pass, so we
can later do gradient accumulation. But all activations have = instead of +=
because these are faster (just read, no write). This is okay for all activations
except for those in the residual stream, where the gradients have to add. We make
sure that those parts work out ok and that we do a += as necessary. E.g.,
the layernorms are connected to the residuals so we += in layernorm backward.
*/

#include <sycl/sycl.hpp>
#include <dpct/dpct.hpp>
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>
#include <assert.h>
#include <float.h>
#include <string.h>
#include <unistd.h>
#include <dpct/blas_utils.hpp>

// GPU / CUDA related
// our own utilities
// defines: fopenCheck, freadCheck, fcloseCheck, fseekCheck, mallocCheck
#include "llmc/utils.h"
// defines: tokenizer_init, tokenizer_decode, tokenizer_free
#include "llmc/tokenizer.h"
// defines: dataloader_init, dataloader_reset, dataloader_next_batch, dataloader_free
#include "llmc/dataloader.h"
#include <dpct/lib_common_utils.hpp>

// ----------------------------------------------------------------------------
// CUDA utils

// convenience macro for calculating grid/block dimensions for kernels
#define CEIL_DIV(M, N) (((M) + (N)-1) / (N))

// CUDA error checking
void cudaCheck(dpct::err0 error, const char *file, int line) {

};
#define cudaCheck(err) (cudaCheck(err, __FILE__, __LINE__))

// cuBLAS error checking
void cublasCheck(int status, const char *file, int line)
{
    if (status != 0) {
        printf("[cuBLAS ERROR]: %d %s %d\n", status, file, line);
        exit(EXIT_FAILURE);
    }
}
#define cublasCheck(status) { cublasCheck((status), __FILE__, __LINE__); }

static dpct::compute_type cublas_compute_type;
dpct::blas::descriptor_ptr cublas_handle;

// ----------------------------------------------------------------------------
// all the kernels

inline sycl::float4 add_float4(const sycl::float4 &a, const sycl::float4 &b) {
    return sycl::float4(a.x() + b.x(), a.y() + b.y(), a.z() + b.z(),
                        a.w() + b.w());
}

// use of float4 leads to using 128-bit LDG / STG instructions in SASS,
// very helpful in memory-bound kernels like encoder_forward
void encoder_forward_kernel3(sycl::float4 *out, const int *inp,
                             const sycl::float4 *wte, const sycl::float4 *wpe,
                             int B, int T, int C) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int C4 = C / 4;
    int idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
              item_ct1.get_local_id(2);
    int N = B * T * C4;
    if (idx < N) {
        int bt = idx / C4;
        int b = bt / T;
        int t = bt % T;
        int c4 = idx % C4;
        int ix = inp[b * T + t];
        out[b * T * C4 + t * C4 + c4] = add_float4(wte[ix * C4 + c4], wpe[t * C4 + c4]);
    }
}

// really bad naive kernel with atomicAdd
void encoder_backward_kernel(float* dwte, float* dwpe,
                                        const float* dout, const int* inp,
                                        int B, int T, int C) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
              item_ct1.get_local_id(2);
    int N = B * T * C;

    if (idx < N) {
        int bt = idx / C;
        int b = bt / T;
        int t = bt % T;
        int c = idx % C;

        int ix = inp[b * T + t];

        const float* dout_btc = dout + b * T * C + t * C + c;
        float* dwte_ix = dwte + ix * C + c;
        float* dwpe_tc = dwpe + t * C + c;

        dpct::atomic_fetch_add<sycl::access::address_space::generic_space>(
            dwte_ix, *dout_btc);
        dpct::atomic_fetch_add<sycl::access::address_space::generic_space>(
            dwpe_tc, *dout_btc);
    }
}

void layernorm_forward_kernel3(float* __restrict__ out, float* __restrict__ mean, float* __restrict__ rstd,
                                    const float*  __restrict__ inp, const float*  __restrict__ weight,
                                    const float* __restrict__ bias, int N, int C) {
    sycl::group<3> block =

    sycl::group<3> block =
        sycl::ext::oneapi::this_work_item::get_work_group<3>();
    sycl::sub_group warp = sycl::ext::oneapi::this_work_item::get_sub_group();
    int idx = sycl::ext::oneapi::this_work_item::get_nd_item<3>().get_group(2) *
                  sycl::ext::oneapi::this_work_item::get_sub_group()
                      .get_group_linear_range() +
              sycl::ext::oneapi::this_work_item::get_sub_group()
                  .get_group_linear_id();
    if(idx >= N) {
        return;
    }

    // the row of input that this group of threads is responsible for
    const float* x = inp + idx * C;

    // mean
    float sum = 0.0f;
    for (int i = sycl::ext::oneapi::this_work_item::get_sub_group()
                     .get_local_linear_id();
         i < C; i += sycl::ext::oneapi::this_work_item::get_sub_group()
                         .get_local_linear_range()) {
        sum += x[i];
    }
    sum = sycl::reduce_over_group(
        sycl::ext::oneapi::this_work_item::get_sub_group(), sum,
        sycl::plus<float>{});
    float m = sum / C;
    if (sycl::ext::oneapi::this_work_item::get_sub_group()
                .get_local_linear_id() == 0 &&
        mean != nullptr) {
        /*
        DPCT1098:15: The '=' expression is used instead of the __stcs call.
        These two expressions do not provide the exact same functionality. Check
        the generated code for potential precision and/or performance issues.
        */
        *(mean + idx) = m;
    }

    // rstd
    sum = 0.0f;
    for (int i = sycl::ext::oneapi::this_work_item::get_sub_group()
                     .get_local_linear_id();
         i < C; i += sycl::ext::oneapi::this_work_item::get_sub_group()
                         .get_local_linear_range()) {
        float diff = x[i] - m;
        sum += diff * diff;
    }
    sum = sycl::reduce_over_group(
        sycl::ext::oneapi::this_work_item::get_sub_group(), sum,
        sycl::plus<float>{});
    float s = sycl::rsqrt(sum / C + 1e-5f);
    if (sycl::ext::oneapi::this_work_item::get_sub_group()
                .get_local_linear_id() == 0 &&
        rstd != nullptr) {
        /*
        DPCT1098:16: The '=' expression is used instead of the __stcs call.
        These two expressions do not provide the exact same functionality. Check
        the generated code for potential precision and/or performance issues.
        */
        *(rstd + idx) = s;
    }

    // final normalization and scaling by weight/bias
    float* o = out + idx * C;
    for (int c = sycl::ext::oneapi::this_work_item::get_sub_group()
                     .get_local_linear_id();
         c < C; c += sycl::ext::oneapi::this_work_item::get_sub_group()
                         .get_local_linear_range()) {
        // load and store using the .cs "streaming" hint to the compiler,
        // indicating that this data will not be reused soon, and can be streamed through the caches
        // this allows the threads to get more cache-hits for the (shared) weight and bias parameters
        /*
        DPCT1098:18: The '*' expression is used instead of the __ldcs call.
        These two expressions do not provide the exact same functionality. Check
        the generated code for potential precision and/or performance issues.
        */
        float n = s * (*(x + c) - m);
        /*
        DPCT1098:17: The '=' expression is used instead of the __stcs call.
        These two expressions do not provide the exact same functionality. Check
        the generated code for potential precision and/or performance issues.
        */
        *(o + c) = n * weight[c] + bias[c];
    }
}

void permute_kernel(float* q, float* k, float* v,
                               const float* inp,
                               int B, int N, int NH, int d) {
    // okay so now, this kernel wants Q,K,V to all be of shape (B, NH, N, d)
    // but instead, we have a single tensor QKV (inp) of shape (B, N, 3, NH, d)
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
              item_ct1.get_local_id(2);
    // Q[b][nh_][n][d_] = inp[b][n][0][nh_][d_]
    if (idx < B * NH * N * d) {
        int b = idx / (NH * N * d);
        int rest = idx % (NH * N * d);
        int nh_ = rest / (N * d);
        rest = rest % (N * d);
        int n = rest / d;
        int d_ = rest % d;
        int inp_idx = (b * N * 3 * NH * d) + (n * 3 * NH * d) + (0 * NH * d) + (nh_ * d) + d_;
        /*
        DPCT1098:19: The '*' expression is used instead of the __ldcs call.
        These two expressions do not provide the exact same functionality. Check
        the generated code for potential precision and/or performance issues.
        */
        q[idx] = inp[inp_idx];
        /*
        DPCT1098:20: The '*' expression is used instead of the __ldcs call.
        These two expressions do not provide the exact same functionality. Check
        the generated code for potential precision and/or performance issues.
        */
        k[idx] = inp[inp_idx + NH * d];
        /*
        DPCT1098:21: The '*' expression is used instead of the __ldcs call.
        These two expressions do not provide the exact same functionality. Check
        the generated code for potential precision and/or performance issues.
        */
        v[idx] = inp[inp_idx + 2 * (NH * d)];
    }
}

void permute_kernel_backward(float* dinp,
                                        const float* dq, const float* dk, const float* dv,
                                        int B, int N, int NH, int d) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
              item_ct1.get_local_id(2);
    if (idx < B * NH * N * d) {
        int b = idx / (NH * N * d);
        int rest = idx % (NH * N * d);
        int nh_ = rest / (N * d);
        rest = rest % (N * d);
        int n = rest / d;
        int d_ = rest % d;

        int inp_idx = (b * N * 3 * NH * d) + (n * 3 * NH * d) + (0 * NH * d) + (nh_ * d) + d_;
        dinp[inp_idx] = dq[idx];
        dinp[inp_idx + NH * d] = dk[idx];
        dinp[inp_idx + 2 * (NH * d)] = dv[idx];
    }
}

void unpermute_kernel(float* inp, float *out, int B, int N, int NH, int d) {
   // out has shape (B, nh, N, d) but we need to unpermute it to (B, N, nh, d)
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
              item_ct1.get_local_id(2);
    // out[b][n][nh_][d_] <- inp[b][nh_][n][d_]
    if (idx < B * NH * N * d) {
        int b = idx / (NH * N * d);
        int rest = idx % (NH * N * d);
        int nh_ = rest / (N * d);
        rest = rest % (N * d);
        int n = rest / d;
        int d_ = rest % d;
        int other_idx = (b * NH * N * d) + (n * NH * d) + (nh_ * d) + d_;
        /*
        DPCT1098:22: The '*' expression is used instead of the __ldcs call.
        These two expressions do not provide the exact same functionality. Check
        the generated code for potential precision and/or performance issues.
        */
        out[other_idx] = inp[idx];
    }
}

void unpermute_kernel_backward(float* dinp, const float *dout, int B, int N, int NH, int d) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
              item_ct1.get_local_id(2);
    if (idx < B * NH * N * d) {
        int b = idx / (NH * N * d);
        int rest = idx % (NH * N * d);
        int nh_ = rest / (N * d);
        rest = rest % (N * d);
        int n = rest / d;
        int d_ = rest % d;
        int other_idx = (b * NH * N * d) + (n * NH * d) + (nh_ * d) + d_;
        dinp[idx] = dout[other_idx];
    }
}

float &vec_at(sycl::float4 &vec, int index) {
    return reinterpret_cast<float*>(&vec)[index];
}

float vec_at(const sycl::float4 &vec, int index) {
    return reinterpret_cast<const float*>(&vec)[index];
}

/*
DPCT1110:0: The total declared local variable size in device function
softmax_forward_kernel5 exceeds 128 bytes and may cause high register pressure.
Consult with your hardware vendor to find the total register size available and
adjust the code, or use smaller sub-group size to avoid high register pressure.
*/
void softmax_forward_kernel5(float *out, float inv_temperature,
                             const float *inp, int N, int T) {

    // inp, out shape: (N, T, T), where N = B * NH
    // fuses the multiplication by scale inside attention
    // directly autoregressive, so we only compute the lower triangular part
    // uses the online softmax algorithm
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
assert(T % 4 == 0);
    sycl::group<3> block =
        sycl::ext::oneapi::this_work_item::get_work_group<3>();
    sycl::sub_group warp = sycl::ext::oneapi::this_work_item::get_sub_group();
    // micro-optimization: we iterate backwards so that
    // after the softmax backward operation completes, the cache retains the
    // part of the matrix close to the upper left corner, which benefits the
    // matmul operation that immediately follows.
    // int idx = blockIdx.x * warp.meta_group_size() + warp.meta_group_rank(); // forward order
    int idx = (item_ct1.get_group_range(2) - item_ct1.get_group(2) - 1) *
                  sycl::ext::oneapi::this_work_item::get_sub_group()
                      .get_group_linear_range() +
              sycl::ext::oneapi::this_work_item::get_sub_group()
                  .get_group_linear_id(); // backward order
    if(idx >= N * T) {
        return;
    }
    int own_pos = idx % T;
    int pos_by_4 = own_pos / 4;

    // one row of inp, i.e. inp[idx, :] of shape (T,)
    const float* x = inp + idx * T;

    // not INF, so we don't get NaNs accidentally when subtracting two values.
    float maxval = -FLT_MAX;
    float sumval = 0.0f;

    const sycl::float4 *x_vec = reinterpret_cast<const sycl::float4 *>(x);
    for (int i = sycl::ext::oneapi::this_work_item::get_sub_group()
                     .get_local_linear_id();
         i < pos_by_4; i += sycl::ext::oneapi::this_work_item::get_sub_group()
                                .get_local_linear_range()) {
        sycl::float4 v = x_vec[i];
        float old_maxval = maxval;
        for(int k = 0; k < 4; ++k) {
            maxval = sycl::fmax(maxval, vec_at(v, k));
        }
        sumval *= sycl::native::exp(inv_temperature * (old_maxval - maxval));
        for(int k = 0; k < 4; ++k) {
            sumval +=
                sycl::native::exp(inv_temperature * (vec_at(v, k) - maxval));
        }
    }

    if (4 * pos_by_4 + sycl::ext::oneapi::this_work_item::get_sub_group()
                           .get_local_linear_id() <=
        own_pos) {
        float old_maxval = maxval;
        maxval = sycl::fmax(
            maxval,
            x[4 * pos_by_4 + sycl::ext::oneapi::this_work_item::get_sub_group()
                                 .get_local_linear_id()]);
        sumval *= sycl::native::exp(inv_temperature * (old_maxval - maxval));
        sumval += sycl::native::exp(
            inv_temperature *
            (x[4 * pos_by_4 + sycl::ext::oneapi::this_work_item::get_sub_group()
                                  .get_local_linear_id()] -
             maxval));
    }

    float global_maxval = sycl::reduce_over_group(
        sycl::ext::oneapi::this_work_item::get_sub_group(), maxval,
        sycl::maximum<float>{});
    sumval *= sycl::native::exp(inv_temperature * (maxval - global_maxval));

    float sum = sycl::reduce_over_group(
        sycl::ext::oneapi::this_work_item::get_sub_group(), sumval,
        sycl::plus<float>{});
    float norm = 1.f / sum;

    // divide the whole row by the sum
    for (int i = sycl::ext::oneapi::this_work_item::get_sub_group()
                     .get_local_linear_id();
         i <= own_pos; i += sycl::ext::oneapi::this_work_item::get_sub_group()
                                .get_local_linear_range()) {
        // recalculation is faster than doing the round-trip through memory.
        /*
        DPCT1098:24: The '*' expression is used instead of the __ldcs call.
        These two expressions do not provide the exact same functionality. Check
        the generated code for potential precision and/or performance issues.
        */
        float ev =
            sycl::native::exp(inv_temperature * (*(x + i) - global_maxval));
        /*
        DPCT1098:23: The '=' expression is used instead of the __stcs call.
        These two expressions do not provide the exact same functionality. Check
        the generated code for potential precision and/or performance issues.
        */
        *(out + idx * T + i) = ev * norm;
    }
}

void residual_forward_kernel(float* out, float* inp1, float* inp2, int N) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
              item_ct1.get_local_id(2);
    if (idx < N) {
        /*
        DPCT1098:25: The '*' expression is used instead of the __ldcs call.
        These two expressions do not provide the exact same functionality. Check
        the generated code for potential precision and/or performance issues.
        */
        out[idx] = inp1[idx] + inp2[idx];
    }
}

#define GELU_SCALING_FACTOR sycl::sqrt((float)(2.0f / M_PI))
void gelu_forward_kernel(float* out, const float* inp, int N) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int i = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
            item_ct1.get_local_id(2);
    if (i < N) {
        float xi = inp[i];
        float cube = 0.044715f * xi * xi * xi;
        out[i] =
            0.5f * xi * (1.0f + sycl::tanh(GELU_SCALING_FACTOR * (xi + cube)));
    }
}

void gelu_backward_kernel(float* dinp, const float* inp, const float* dout, const int N) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int i = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
            item_ct1.get_local_id(2);
    if (i < N) {
        float x = inp[i];
        float cube = 0.044715f * x * x * x;
        float tanh_arg = GELU_SCALING_FACTOR * (x + cube);
        float tanh_out = sycl::tanh(tanh_arg);
        float coshf_out = sycl::cosh(tanh_arg);
        float sech_out = 1.0f / (coshf_out * coshf_out);
        float local_grad = 0.5f * (1.0f + tanh_out) + x * 0.5f * sech_out * GELU_SCALING_FACTOR * (1.0f + 3.0f * 0.044715f * x * x);
        dinp[i] = local_grad * dout[i];
    }
}

// this kernel performs a column-wise reduction over dout, in PyTorch equivalent to:
// dbias = dout.sum((0,1))
// the idea is to employ one block to reduce along several columns,
// where each block has a width of 32 columns to ensure coalesced access.
// at the end we accumulate the reductions performed by the warps in each block via shared memory
void matmul_backward_bias_kernel4(float* dbias, const float* dout, int B, int T, int OC,
                                  uint8_t *dpct_local) {
    // this kernel is launched with 1D grid_dim of OC/32
    // for example let's say block_size is 128
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    auto smem = (float *)dpct_local; // of size block_size (128)
    const int warp_id = item_ct1.get_local_id(2) /
                        sycl::ext::oneapi::this_work_item::get_sub_group()
                            .get_local_range()
                            .get(0); // warp index in the block, 0,1,2,3
    const int lane_id = item_ct1.get_local_id(2) %
                        sycl::ext::oneapi::this_work_item::get_sub_group()
                            .get_local_range()
                            .get(0); // thread index in the warp, 0,1,2,...,31
    const int tl = item_ct1.get_group(2) *
                   sycl::ext::oneapi::this_work_item::get_sub_group()
                       .get_local_range()
                       .get(0); // pointer to the start column for this block
    const int vstep = item_ct1.get_local_range(2) /
                      sycl::ext::oneapi::this_work_item::get_sub_group()
                          .get_local_range()
                          .get(0); // number of warps in a block, e.g. 4

    // pointer to the start of the column for one lane of threads
    // so e.g. 4 threads (of the same lane_id) will reduce this one column
    const float* dout_col = dout + tl + lane_id;

    // column reductions by looping through the rows
    // each of the 4 threads offsets by its warp_id and then skips by vstep
    // together these 4 threads cover all B*T rows of this (lane_id) column
    // importantly, consecutive threads (in threadId) are processing adjacent columns,
    // leading to a coalesced memory access pattern
    float dout_sum = 0.0f;
    for (int row = warp_id; row < B * T; row += vstep) {
        dout_sum += dout_col[row * OC];
    }
    smem[lane_id + warp_id * sycl::ext::oneapi::this_work_item::get_sub_group()
                                 .get_local_range()
                                 .get(0)] = dout_sum;
    /*
    DPCT1065:26: Consider replacing sycl::nd_item::barrier() with
    sycl::nd_item::barrier(sycl::access::fence_space::local_space) for better
    performance if there is no access to global memory.
    */
    item_ct1.barrier();

    // warp_id 0 reduces the shared memory column-wise, linearly
    dout_sum = 0.0f;
    if (warp_id == 0) {
        for (int j = 0; j < vstep; j++) {
            dout_sum +=
                smem[lane_id +
                     j * sycl::ext::oneapi::this_work_item::get_sub_group()
                             .get_local_range()
                             .get(0)];

        }
        dbias[tl + lane_id] += dout_sum;
    }
}

// uses shared memory instead for the reduces
/*
DPCT1110:1: The total declared local variable size in device function
layernorm_backward_kernel2 exceeds 128 bytes and may cause high register
pressure. Consult with your hardware vendor to find the total register size
available and adjust the code, or use smaller sub-group size to avoid high
register pressure.
*/
void layernorm_backward_kernel2(float *dinp, float *dweight, float *dbias,
                                const float *dout, const float *inp,
                                const float *weight, const float *mean,
                                const float *rstd, int B, int T, int C,
                                uint8_t *dpct_local) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    auto shared = (float *)dpct_local; // size = 2 * C

    sycl::group<3> block =
        sycl::ext::oneapi::this_work_item::get_work_group<3>();
    sycl::sub_group warp = sycl::ext::oneapi::this_work_item::get_sub_group();
    int idx = item_ct1.get_group(2) *
                  sycl::ext::oneapi::this_work_item::get_sub_group()
                      .get_group_linear_range() +
              sycl::ext::oneapi::this_work_item::get_sub_group()
                  .get_group_linear_id();
    int N = B * T;
    if(idx >= N) { return; } // thread guards

    int b = idx / T;
    int t = idx % T;

    const float* dout_bt = dout + b * T * C + t * C;
    const float* inp_bt = inp + b * T * C + t * C;
    float* dinp_bt = dinp + b * T * C + t * C;
    const float mean_bt = mean[b * T + t];
    const float rstd_bt = rstd[b * T + t];

    // the first half of shared memory is bias, second is weight
    float* dbias_shared = shared;
    float* dweight_shared = shared + C;

    // init shared memory to zero
    #pragma unroll
        for (int i = item_ct1.get_local_id(2); i < C;
             i += item_ct1.get_local_range(2)) {
       dbias_shared[i] = 0.0f;
       dweight_shared[i] = 0.0f;
    }
    /*
    DPCT1065:27: Consider replacing sycl::nd_item::barrier() with
    sycl::nd_item::barrier(sycl::access::fence_space::local_space) for better
    performance if there is no access to global memory.
