void matmul_forward_kernel4(float *out, const float *inp, const float *weight,
                            const float *bias, int C, int OC,
                            float lhs_s[128][32], float rhs_s[128][32]) {
    // out is (B,T,OC). OC is short for "output channels", e.g. OC = 4 * C
    // inp is (B,T,C), weight is (OC, C), bias is (OC)
    // each thread handles 8x8 elements; each block 128 by 128 elements.
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int oc = 8 * (item_ct1.get_group(1) * item_ct1.get_local_range(1) +
                  item_ct1.get_local_id(1));

    // buffers to cache chunks of the input matrices

    // adjust our pointers for the current block
    inp += 128 * item_ct1.get_group(2) * C;
    weight += 128 * item_ct1.get_group(1) * C;
    out += 128 * item_ct1.get_group(2) * OC + 128 * item_ct1.get_group(1);

    float vals[8][8] = {};
    if(bias != NULL) {
        for (int i = 0; i < 8; i++) {
            for (int j = 0; j < 8; j += 4) {
                sycl::float4 b = ld_vec(bias + oc + j);
                vals[i][j + 0] = b.x();
                vals[i][j + 1] = b.y();
                vals[i][j + 2] = b.z();
                vals[i][j + 3] = b.w();
            }
        }
    }

    int si_start =
        4 * (16 * item_ct1.get_local_id(1) + item_ct1.get_local_id(2));
    for (int so = 0; so < C; so += 32) {
        /*
        DPCT1118:4: SYCL group functions and algorithms must be encountered in
        converged control flow. You may need to adjust the code.
        */
        item_ct1.barrier(sycl::access::fence_space::local_space);
        int xmod8 = item_ct1.get_local_id(2) % 8;
        int xby8 = item_ct1.get_local_id(2) / 8;
        int xo = 4 * xmod8;
        for (int y = 2 * item_ct1.get_local_id(1) + xby8; y < 128; y += 32) {
            st_vec(&lhs_s[y][xo], ld_vec(inp + y * C + so + xo));
            st_vec(&rhs_s[y][xo], ld_vec(weight + y * C + so + xo));
        }
        /*
        DPCT1118:5: SYCL group functions and algorithms must be encountered in
        converged control flow. You may need to adjust the code.
        */
        item_ct1.barrier(sycl::access::fence_space::local_space);

        for (int si = si_start; si < si_start + 32; si += 4) {
            sycl::float4 rhs[8];
            for (int u = 0; u < 8; ++u) {
                rhs[u] =
                    ld_vec(&rhs_s[u + 8 * item_ct1.get_local_id(1)][si % 32]);
            }

            for (int ii = 0; ii < 8; ++ii) {
                sycl::float4 lhs =
                    ld_vec(&lhs_s[ii + 8 * item_ct1.get_local_id(2)][si % 32]);
                for (int ji = 0; ji < 8; ++ji) {
                    vals[ii][ji] += lhs.x() * rhs[ji].x();
                    vals[ii][ji] += lhs.y() * rhs[ji].y();
                    vals[ii][ji] += lhs.z() * rhs[ji].z();
                    vals[ii][ji] += lhs.w() * rhs[ji].w();
                }
            }
        }
    }

    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; j += 4) {
            sycl::float4 result;
            result.x() = vals[i][j + 0];
            result.y() = vals[i][j + 1];
            result.z() = vals[i][j + 2];
            result.w() = vals[i][j + 3];
            st_vec(out + (8 * item_ct1.get_local_id(2) + i) * OC +
                       8 * item_ct1.get_local_id(1) + j,
                   result);
        }
    }
}


