    float *wpe = nullptr;      // (maxT, C)
    float *ln1w = nullptr;     // (L, C)
    float *ln1b = nullptr;
    float *qkvw = nullptr;     // (L, 3C, C)
    float *qkvb = nullptr;     // (L, 3C)
